script:
// Currency cascade: tenant -> property -> company.
// Only fills `currency` when it is blank, so a manual override is never lost.
frappe.ui.form.on('PS Lease Agreement', {
	refresh: function (frm) { ps_currency_cascade(frm); },
	tenant: function (frm) { ps_currency_cascade(frm); },
	property: function (frm) { ps_currency_cascade(frm); },
	company: function (frm) { ps_currency_cascade(frm); }
});

function ps_currency_cascade(frm) {
	if (!frm || !frm.doc || frm.doc.currency) return;

	// Resolve one source; returns a Promise of a currency code or null.
	function look(doctype, name, field) {
		if (!name) return Promise.resolve(null);
		try {
			return frappe.db.get_value(doctype, name, field)
				.then(function (r) {
					return (r && r.message && r.message[field]) || null;
				})
				.catch(function () { return null; });
		} catch (e) {
			return Promise.resolve(null);
		}
	}

	look('Tenant', frm.doc.tenant, 'default_currency')
		.then(function (cur) {
			return cur || look('PS Property', frm.doc.property, 'currency');
		})
		.then(function (cur) {
			return cur || look('Company', frm.doc.company, 'default_currency');
		})
		.then(function (cur) {
			// Re-check emptiness: the user may have typed while we were waiting.
			if (cur && !frm.doc.currency) {
				frm.set_value('currency', cur);
			}
		})
		.catch(function () { /* never block the form */ });
}

// Currency cascade: customer -> property -> company.
// Only fills `currency` when it is blank, so a manual override is never lost.
frappe.ui.form.on('Property Sale Contract', {
	refresh: function (frm) { ps_sale_currency_cascade(frm); },
	customer: function (frm) { ps_sale_currency_cascade(frm); },
	property: function (frm) { ps_sale_currency_cascade(frm); },
	company: function (frm) { ps_sale_currency_cascade(frm); }
});

function ps_sale_currency_cascade(frm) {
	if (!frm || !frm.doc || frm.doc.currency) return;

	function look(doctype, name, field) {
		if (!name) return Promise.resolve(null);
		try {
			return frappe.db.get_value(doctype, name, field)
				.then(function (r) {
					return (r && r.message && r.message[field]) || null;
				})
				.catch(function () { return null; });
		} catch (e) {
			return Promise.resolve(null);
		}
	}

	look('Customer', frm.doc.customer, 'default_currency')
		.then(function (cur) {
			return cur || look('PS Property', frm.doc.property, 'currency');
		})
		.then(function (cur) {
			return cur || look('Company', frm.doc.company, 'default_currency');
		})
		.then(function (cur) {
			if (cur && !frm.doc.currency) {
				frm.set_value('currency', cur);
			}
		})
		.catch(function () { /* never block the form */ });
}

// Adds a 'Create Rent Invoice' button to a submitted lease.
// Finds the oldest unbilled period on the rent schedule (arrears first)
// and opens a fully pre-filled Sales Invoice draft. Nothing is saved or
// submitted automatically - the user reviews the draft and submits it.
//
// On submit, the server script 'PS Rent Schedule Writeback' marks the
// schedule row Invoiced. When payment lands, 'PS Rent Schedule Payment
// Sync' flips it to Paid. Cancelling the invoice releases the period.

frappe.ui.form.on('PS Lease Agreement', {
    refresh: function (frm) {
        try {
            if (frm.doc.docstatus !== 1) { return; }
            var stopped = ['Terminated', 'Cancelled'];
            if (stopped.indexOf(frm.doc.lease_status) !== -1) { return; }

            frm.add_custom_button(__('Create Rent Invoice'), function () {
                ps_create_rent_invoice(frm);
            }).addClass('btn-primary');

            // quick sight of where the account stands
            var rows = frm.doc.rent_schedule || [];
            var due = 0, overdue = 0, unbilled = 0;
            rows.forEach(function (r) {
                if (!r.sales_invoice) { unbilled += 1; }
                if (r.invoice_status === 'Overdue') { overdue += 1; }
                due += (flt(r.total_due) - flt(r.amount_paid));
            });
            if (overdue > 0) {
                frm.dashboard.set_headline_alert(
                    __('{0} period(s) overdue. Outstanding {1}',
                       [overdue, format_currency(due, frm.doc.currency)]),
                    'orange');
            }
        } catch (e) {
            console.error('Create Rent Invoice button failed to load:', e);
        }
    }
});

async function ps_create_rent_invoice(frm) {
    try {
        var rows = frm.doc.rent_schedule || [];
        var row = null;

        // arrears first: any row with no invoice against it, oldest due date wins.
        var candidates = [];
        for (var i = 0; i < rows.length; i++) {
            var st = rows[i].invoice_status;
            if (!rows[i].sales_invoice &&
                (st === 'Not Invoiced' || st === 'Overdue' || !st)) {
                candidates.push(rows[i]);
            }
        }
        candidates.sort(function (a, b) {
            return (a.due_date || '9999-12-31') > (b.due_date || '9999-12-31') ? 1 : -1;
        });
        row = candidates.length ? candidates[0] : null;

        if (!row) {
            frappe.msgprint({
                title: __('Nothing left to invoice'),
                indicator: 'blue',
                message: __('Every period on this rent schedule has already been invoiced.')
            });
            return;
        }

        var period = row.period_label || (row.due_date || '');
        frappe.dom.freeze(__('Preparing the invoice...'));

        // --- company fallbacks -----------------------------------------------
        var co = await frappe.db.get_value('Company', frm.doc.company,
            ['default_income_account', 'cost_center']);
        var co_msg = (co && co.message) ? co.message : {};
        var default_income = co_msg.default_income_account || null;
        var default_cc = co_msg.cost_center || null;

        // --- decide the lines -------------------------------------------------
        var lines = [];
        if (frm.doc.rent_item && flt(row.rent_amount) > 0) {
            lines.push({ item_code: frm.doc.rent_item, rate: flt(row.rent_amount),
                         description: 'Rent - ' + period });
        }
        (frm.doc.charges || []).forEach(function (c) {
            if (c.include_in_rent_invoice && c.item_code && flt(c.amount) > 0) {
                lines.push({ item_code: c.item_code, rate: flt(c.amount),
                             description: (c.description || c.charge_type || 'Charge') + ' - ' + period });
            }
        });

        if (!lines.length) {
            frappe.dom.unfreeze();
            frappe.msgprint(__('This lease has no rent item or billable charges set, so there is nothing to invoice.'));
            return;
        }

        // --- pull everything ERPNext validates on each line -------------------
        for (var j = 0; j < lines.length; j++) {
            var item = await frappe.db.get_doc('Item', lines[j].item_code);
            lines[j].item_name = item.item_name || lines[j].item_code;
            lines[j].uom = item.sales_uom || item.stock_uom || 'Nos';
            lines[j].stock_uom = item.stock_uom || 'Nos';

            var def = null;
            (item.item_defaults || []).forEach(function (d) {
                if (d.company === frm.doc.company) { def = d; }
            });
            lines[j].income_account = (def && def.income_account) ? def.income_account : default_income;
            lines[j].cost_center = (def && def.selling_cost_center) ? def.selling_cost_center : default_cc;
        }

        // --- build the draft --------------------------------------------------
        frappe.model.with_doctype('Sales Invoice', function () {
            var si = frappe.model.get_new_doc('Sales Invoice');

            si.customer = frm.doc.customer;
            si.company = frm.doc.company;
            si.currency = frm.doc.currency;
            si.conversion_rate = frm.doc.exchange_rate || 1;
            si.selling_price_list = 'Standard Selling';
            si.price_list_currency = frm.doc.currency;
            si.plc_conversion_rate = frm.doc.exchange_rate || 1;
            si.posting_date = frappe.datetime.get_today();
            si.set_posting_time = 1;
            si.due_date = row.due_date;
            si.property = frm.doc.property;
            si.property_unit = frm.doc.property_unit;

            // these two drive the rent schedule write-back on submit
            si.ps_lease_agreement = frm.doc.name;
            si.ps_schedule_row = row.name;

            si.remarks = 'Rent for ' + period + ' under lease ' + frm.doc.name;

            lines.forEach(function (l) {
                var d = frappe.model.add_child(si, 'Sales Invoice Item', 'items');
                d.item_code = l.item_code;
                d.item_name = l.item_name;
                d.description = l.description;
                d.uom = l.uom;
                d.stock_uom = l.stock_uom;
                d.conversion_factor = 1;
                d.qty = 1;
                d.stock_qty = 1;
                d.rate = l.rate;
                d.price_list_rate = l.rate;
                d.amount = l.rate;
                d.base_rate = l.rate;
                d.base_amount = l.rate;
                d.income_account = l.income_account;
                d.cost_center = l.cost_center;
                d.property = frm.doc.property;
                d.property_unit = frm.doc.property_unit;
            });

            frappe.dom.unfreeze();
            frappe.set_route('Form', 'Sales Invoice', si.name);
            frappe.show_alert({ message: __('Draft invoice prepared for {0}. Submit it and the schedule will update.', [period]),
                                indicator: 'green' }, 7);
        });
    } catch (e) {
        frappe.dom.unfreeze();
        console.error(e);
        frappe.msgprint({
            title: __('Could not prepare the invoice'),
            indicator: 'red',
            message: __('Please raise the Sales Invoice manually. Details are in the browser console.')
        });
    }
}
